cat > src/orchestration/tools/registry.acceptance.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

describe('tool input validation', () => {
  it('rejects invalid inputs and passes valid input through unchanged', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'weather',
        description: 'Forecast',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}, unit: {type: 'string', enum: ['C', 'F'], default: 'C'}},
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return 'forecast';
      }
    );
    const missing = await registry.execute('weather', {});
    const wrongType = await registry.execute('weather', {location: 123456789});
    const wrongEnum = await registry.execute('weather', {location: 'Berlin', unit: 'secret-unit'});
    const valid = {location: 'Berlin', extra: 'unchanged'};
    const success = await registry.execute('weather', valid);

    expect(missing.result).toMatch(/location/i);
    expect(missing.result).toMatch(/required/i);
    expect(wrongType.result).toMatch(/location/i);
    expect(wrongType.result).toMatch(/string/i);
    expect(wrongType.result).not.toContain('123456789');
    expect(wrongEnum.result).toMatch(/unit/i);
    expect(wrongEnum.result).toMatch(/enum|allowed/i);
    expect(wrongEnum.result).not.toContain('secret-unit');
    expect(success.result).toBe('forecast');
    expect(received).toEqual([valid]);
  });

  it('validates each function-valued definition against its current schema', async () => {
    const registry = new ToolRegistry();
    let required = 'location';
    const received: Record<string, unknown>[] = [];
    registry.register(
      () => ({
        name: 'dynamic',
        description: 'Dynamic schema',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}, date: {type: 'string'}}, required: [required]},
      }),
      async input => {
        received.push(input);
        return 'executed';
      }
    );
    const first = await registry.execute('dynamic', {location: 'Berlin'});
    required = 'date';
    const rejected = await registry.execute('dynamic', {location: 'Berlin'});
    const second = await registry.execute('dynamic', {date: 'tomorrow'});

    expect(first.result).toBe('executed');
    expect(rejected.result).toMatch(/date/i);
    expect(rejected.result).toMatch(/required/i);
    expect(second.result).toBe('executed');
    expect(received).toEqual([{location: 'Berlin'}, {date: 'tomorrow'}]);
  });

  it('rejects an uncompilable static schema at registration with the tool name', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {name: 'broken-weather', description: 'Invalid schema', inputSchema: {type: 'not-a-json-schema-type'}},
        async () => 'executed'
      )
    ).toThrow(/broken-weather/i);
  });
});
EOF
mkdir -p .lore
cat > .lore/dod.md <<'EOF'
# Definition of Done

> "'`ToolRegistry.execute` looks a tool up, logs the input'"'s key names, and calls the executor without ever checking the declared "'`inputSchema` (`src/orchestration/tools/registry.ts`).

**Strategy: `direct`** — `ToolRegistry.register` and `execute` expose the real tool boundary and accept real schemas and executors.

## Done when these pass

- [ ] **rejects invalid inputs and passes valid input through unchanged** — Required fields, types and enums reject without invoking the executor or exposing values; valid inputs retain extra properties and receive no defaults or coercion.
  `src/orchestration/tools/registry.acceptance.test.ts`
- [ ] **validates each function-valued definition against its current schema** — Each call uses the resolved schema rather than a stale definition.
  `src/orchestration/tools/registry.acceptance.test.ts`
- [ ] **rejects an uncompilable static schema at registration with the tool name** — Invalid static schemas fail at startup with an actionable tool name.
  `src/orchestration/tools/registry.acceptance.test.ts`

## Facets

- [ ] Compile static schemas on registration and cache dynamic schemas by resolved object; retain the existing unknown-tool exception.
- [ ] Validate before invoking tools and return actionable, value-free rejection results and logs; preserve accepted input unchanged.
- [ ] Verify static schemas compile once and a rejected call can be corrected in the bounded orchestrator tool loop.
- [ ] Update the named documentation, contract comment, changelog, dependency and minor version; include the migration note in the PR.
- [ ] Run the repository'"'s required CI checks.

## Out of scope

- Tool output validation, authorization, unknown-tool behavior changes, execution retries, timeouts and rate limits.
EOF
cat > specs/hal-engine-tool-input-validation/spec.md <<'EOF'
# Tool input validation

| Field  | Value |
| ------ | ----- |
| Issue  | re-cinq/HALEngine#37 |
| Status | Draft |

Tool input validation protects executors and gives the model an opportunity to correct malformed calls.

## Contract

- The registry rejects missing required properties, wrong types and enum values with a ToolResponse describing the property and constraint without disclosing values, and passes valid input including extra properties unchanged to the executor exactly once ([validated by: rejects invalid inputs and passes valid input through unchanged](../../src/orchestration/tools/registry.acceptance.test.ts#L4)).
- A function-valued definition is validated using its current resolved schema on each call ([validated by: validates each function-valued definition against its current schema](../../src/orchestration/tools/registry.acceptance.test.ts#L42)).
- An uncompilable static schema fails at registration with an error naming the tool ([validated by: rejects an uncompilable static schema at registration with the tool name](../../src/orchestration/tools/registry.acceptance.test.ts#L70)).
EOF
